package com.mercadototal.cliente;
import com.google.firebase.Timestamp;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.ListenerRegistration;
import java.util.*;
public class Repo {
 public interface Callback<T>{void ok(T r);void error(String m);}
 private static FirebaseFirestore db(){return FirebaseFirestore.getInstance();}
 private static String uid(){return FirebaseAuth.getInstance().getCurrentUser().getUid();}
 public static void perfil(Callback<Map<String,Object>> cb){db().collection("users").document(uid()).get().addOnSuccessListener(d->{Map<String,Object> m=d.exists()?d.getData():new HashMap<>();cb.ok(m==null?new HashMap<>():m);}).addOnFailureListener(e->cb.error(e.getMessage()));}
 public static ListenerRegistration escucharTasaUSD(Callback<Double> cb){return db().collection("configuracion").document("tasaUSD").addSnapshotListener((d,e)->{if(e!=null){cb.error(e.getMessage());return;}Object v=d==null?null:d.get("valor");cb.ok(v instanceof Number?((Number)v).doubleValue():0d);});}
 public static void productos(Callback<List<Producto>> cb){db().collection("productos").whereEqualTo("activo",true).get().addOnSuccessListener(q->{List<Producto> l=new ArrayList<>();for(DocumentSnapshot d:q.getDocuments())try{Producto p=new Producto();p.id=d.getId();p.nombre=d.getString("nombre");p.categoria=d.getString("categoria");p.foto=d.getString("foto");p.tipoExistencia=d.getString("tipoExistencia");p.unidadMedida=d.getString("unidadMedida");Object pr=d.get("precio"),ex=d.get("existencia");p.precio=pr instanceof Number?((Number)pr).doubleValue():0;p.existencia=ex instanceof Number?((Number)ex).doubleValue():0;if(p.nombre!=null&&p.existencia>0)l.add(p);}catch(Exception ignored){}Collections.sort(l,(a,b)->a.nombre.compareToIgnoreCase(b.nombre));cb.ok(l);}).addOnFailureListener(e->cb.error(e.getMessage()));}
 public static void enviarPedido(Map<String,Object> perfil,String direccion,Callback<Void> cb){db().collection("configuracion").document("tasaUSD").get().addOnSuccessListener(td->{Object tv=td.get("valor");double tasa=tv instanceof Number?((Number)tv).doubleValue():0;List<Map<String,Object>> its=new ArrayList<>();for(ItemCarrito i:Carrito.items){Map<String,Object> m=new HashMap<>();m.put("productoId",i.productoId);m.put("nombre",i.nombre);m.put("precio",i.precio);m.put("cantidad",i.cantidad);m.put("unidadMedida",i.unidadMedida);its.add(m);}Map<String,Object> p=new HashMap<>();p.put("clienteId",uid());p.put("clienteNombre",perfil.get("nombre"));p.put("telefono",perfil.get("telefono"));p.put("direccion",direccion);p.put("items",its);p.put("total",Carrito.total());p.put("tasaUSD",tasa);p.put("totalUSD",tasa>0?Carrito.total()/tasa:0);p.put("estado","pendiente");p.put("fecha",FieldValue.serverTimestamp());p.put("tipoEntrega","domicilio");db().collection("pedidos").add(p).addOnSuccessListener(r->cb.ok(null)).addOnFailureListener(e->cb.error(e.getMessage()));}).addOnFailureListener(e->cb.error("No se pudo consultar la tasa USD: "+e.getMessage()));}
 @SuppressWarnings("unchecked") public static ListenerRegistration misPedidos(Callback<List<Pedido>> cb){return db().collection("pedidos").whereEqualTo("clienteId",uid()).limit(50).addSnapshotListener((s,e)->{if(e!=null){cb.error(e.getMessage());return;}if(s==null)return;List<Pedido> l=new ArrayList<>();for(DocumentSnapshot d:s.getDocuments())try{Pedido p=new Pedido();p.id=d.getId();p.direccion=d.getString("direccion");p.estado=d.getString("estado");Object t=d.get("total");p.total=t instanceof Number?((Number)t).doubleValue():0;Timestamp ts=d.getTimestamp("fecha");p.fecha=ts==null?null:ts.toDate();Object raw=d.get("items");if(raw instanceof List)for(Object o:(List<?>)raw)if(o instanceof Map){Map<String,Object> m=(Map<String,Object>)o;Pedido.Linea x=new Pedido.Linea();x.nombre=String.valueOf(m.get("nombre"));Object c=m.get("cantidad");x.cantidad=c instanceof Number?((Number)c).doubleValue():0;p.lineas.add(x);}if(p.estado==null)p.estado="pendiente";l.add(p);}catch(Exception ignored){}Collections.sort(l,(a,b)->Long.compare(b.fecha==null?Long.MIN_VALUE:b.fecha.getTime(),a.fecha==null?Long.MIN_VALUE:a.fecha.getTime()));cb.ok(l);});}
 public static void cancelarPedido(String id,Callback<Void> cb){db().collection("pedidos").document(id).update("estado","cancelado").addOnSuccessListener(r->cb.ok(null)).addOnFailureListener(e->cb.error(e.getMessage()));}
}